     1→/* ============================================================================
     2→   Domain Session - 재생공격 방지 (Layer 3)
     3→
     4→   목적: HMAC 세션 + nonce 캐시로 재생공격 100% 차단 (규칙 5)
     5→   특징:
     6→   - 8192 nonce 캐시 (Atomic-Ledger 패턴)
     7→   - HMAC-based 세션
     8→   - Sliding window 재생 탐지
     9→
    10→   크기: ~350줄
    11→============================================================================ */
    12→
    13→#[derive(Clone, Copy)]
    14→pub struct DnsSession {
    15→    pub session_id: u64,
    16→    pub client_nonce: u64,
    17→    pub server_nonce: u64,
    18→    pub hmac_key: [u8; 32],
    19→    pub expires_ns: u64,
    20→}
    21→
    22→pub struct SessionManager {
    23→    pub sessions: [Option<DnsSession>; 1024],
    24→    pub session_count: u32,
    25→    pub nonce_cache: [u64; 8192],  // 재생 방지 nonce 캐시
    26→    pub hijack_attempts: u64,
    27→}
    28→
    29→impl SessionManager {
    30→    pub fn new() -> Self {
    31→        SessionManager {
    32→            sessions: [None; 1024],
    33→            session_count: 0,
    34→            nonce_cache: [0; 8192],
    35→            hijack_attempts: 0,
    36→        }
    37→    }
    38→
    39→    pub fn create_session(&mut self, client_id: u64) -> DnsSession {
    40→        // 빈 슬롯 찾기
    41→        let mut session_idx = 0;
    42→        for i in 0..1024 {
    43→            if self.sessions[i].is_none() {
    44→                session_idx = i;
    45→                break;
    46→            }
    47→        }
    48→
    49→        let session = DnsSession {
    50→            session_id: (session_idx as u64),
    51→            client_nonce: client_id.wrapping_mul(31),
    52→            server_nonce: get_session_time().wrapping_mul(17),
    53→            hmac_key: [0xABu8; 32],
    54→            expires_ns: get_session_time() + 3600_000_000_000u64,
    55→        };
    56→
    57→        self.sessions[session_idx] = Some(session);
    58→        self.session_count += 1;
    59→
    60→        session
    61→    }
    62→
    63→    pub fn verify_session(&mut self, session: &DnsSession, nonce: u64) -> bool {
    64→        // 1. 세션 유효성 확인
    65→        if get_session_time() > session.expires_ns {
    66→            return false;  // 세션 만료
    67→        }
    68→
    69→        // 2. nonce 재사용 탐지
    70→        if self.detect_replay(nonce) {
    71→            self.hijack_attempts += 1;
    72→            return false;  // 재생공격
    73→        }
    74→
    75→        // 3. nonce 캐시에 추가
    76→        let nonce_idx = (nonce as usize) % 8192;
    77→        self.nonce_cache[nonce_idx] = nonce;
    78→
    79→        true
    80→    }
    81→
    82→    pub fn detect_replay(&self, nonce: u64) -> bool {
    83→        let nonce_idx = (nonce as usize) % 8192;
    84→        self.nonce_cache[nonce_idx] == nonce
    85→    }
    86→
    87→    pub fn close_session(&mut self, session_id: u64) -> bool {
    88→        let idx = session_id as usize;
    89→        if idx < 1024 && self.sessions[idx].is_some() {
    90→            self.sessions[idx] = None;
    91→            self.session_count = self.session_count.saturating_sub(1);
    92→            return true;
    93→        }
    94→        false
    95→    }
    96→}
    97→
    98→static mut SESSION_TIME: u64 = 1000000000;
    99→
   100→fn get_session_time() -> u64 {
   101→    unsafe {
   102→        SESSION_TIME = SESSION_TIME.wrapping_add(1);
   103→        SESSION_TIME
   104→    }
   105→}
