   271→struct KBucket {
   272→    nodes: [Option<DhtContact>; 20],
   273→    count: u8,
   274→}
   275→
   276→impl KBucket {
   277→    fn new() -> Self {
   278→        KBucket {
   279→            nodes: [None; 20],
   280→            count: 0,
   281→        }
   282→    }
   283→
   284→    fn insert(&mut self, contact: DhtContact) -> bool {
   285→        for i in 0..self.count as usize {
   286→            if let Some(existing) = &self.nodes[i] {
   287→                if existing.node_id.bytes == contact.node_id.bytes {
   288→                    self.nodes[i] = Some(contact);
   289→                    return false;
   290→                }
   291→            }
   292→        }
   293→
   294→        if self.count < 20 {
   295→            self.nodes[self.count as usize] = Some(contact);
   296→            self.count += 1;
   297→            return true;
   298→        }
   299→
   300→        self.nodes[0] = Some(contact);
   301→        false
   302→    }
   303→
   304→    fn get_closest_node(&self, target: &NodeId) -> Option<DhtContact> {
   305→        let mut closest: Option<DhtContact> = None;
   306→        let mut min_distance = [255u8; 20];
   307→
   308→        for i in 0..self.count as usize {
   309→            if let Some(contact) = &self.nodes[i] {
   310→                let dist = contact.node_id.xor_distance(target);
   311→                let mut is_closer = false;
   312→                for j in 0..20 {
   313→                    if dist.bytes[j] < min_distance[j] {
   314→                        is_closer = true;
   315→                        break;
   316→                    } else if dist.bytes[j] > min_distance[j] {
   317→                        break;
   318→                    }
   319→                }
   320→
   321→                if is_closer {
   322→                    closest = Some(*contact);
   323→                    for j in 0..20 {
   324→                        min_distance[j] = dist.bytes[j];
   325→                    }
   326→                }
   327→            }
   328→        }
   329→
   330→        closest
   331→    }
   332→}
