   340→impl DhtTable {
   341→    fn new(self_id: NodeId) -> Self {
   342→        let mut buckets: [KBucket; 160] = unsafe {
   343→            std::mem::MaybeUninit::uninit().assume_init()
   344→        };
   345→
   346→        for i in 0..160 {
   347→            buckets[i] = KBucket::new();
   348→        }
   349→
   350→        DhtTable {
   351→            buckets,
   352→            self_id,
   353→            total_contacts: 0,
   354→        }
   355→    }
   356→
   357→    fn insert_contact(&mut self, contact: DhtContact) {
   358→        let bucket_idx = self.self_id.bucket_index(&contact.node_id) as usize;
   359→        if bucket_idx < 160 {
   360→            let is_new = self.buckets[bucket_idx].insert(contact);
   361→            if is_new {
   362→                self.total_contacts += 1;
   363→            }
   364→        }
   365→    }
   366→
   367→    fn remove_contact(&mut self, node_id: &NodeId) {
   368→        let bucket_idx = self.self_id.bucket_index(node_id) as usize;
   369→        if bucket_idx < 160 {
   370→            for i in 0..self.buckets[bucket_idx].count as usize {
   371→                if let Some(contact) = &self.buckets[bucket_idx].nodes[i] {
   372→                    if contact.node_id.bytes == node_id.bytes {
   373→                        for j in i..self.buckets[bucket_idx].count as usize - 1 {
   374→                            self.buckets[bucket_idx].nodes[j] = self.buckets[bucket_idx].nodes[j + 1];
   375→                        }
   376→                        self.buckets[bucket_idx].count -= 1;
   377→                        self.total_contacts = self.total_contacts.saturating_sub(1);
   378→                        return;
   379→                    }
   380→                }
   381→            }
   382→        }
   383→    }
   384→
   385→    fn get_k_closest(&self, target: &NodeId, k: usize) -> Vec<DhtContact> {
   386→        let mut closest: Vec<DhtContact> = Vec::new();
   387→        let bucket_idx = self.self_id.bucket_index(target) as usize;
   388→
   389→        for i in 0..self.buckets[bucket_idx].count as usize {
   390→            if let Some(contact) = &self.buckets[bucket_idx].nodes[i] {
   391→                closest.push(*contact);
   392→            }
   393→        }
   394→
   395→        if closest.len() > k {
   396→            closest.truncate(k);
   397→        }
   398→
   399→        closest
   400→    }
